-- Hand the trees to Talented as soon as it loads. !TemucraftCompat loads first, so this runs before Talented's own
-- setup (AceAddon) on the same ADDON_LOADED, and Talented never compares the game with its stock copy.
local loader = CreateFrame("Frame")
loader:RegisterEvent("ADDON_LOADED")
loader:SetScript("OnEvent", function(self, _, name)
	if name ~= "Talented" then return end
	local talented = _G.Talented
	if talented and type(talented.spelldata) == "table" then
		for class, data in pairs(TemucraftTalentedData) do talented.spelldata[class] = data end
	end
	self:UnregisterEvent("ADDON_LOADED")
end)
